export function stringToTypedArray(r,t=!1){return t?"fromBase64"in Uint8Array?Uint8Array.fromBase64(r):"function"==typeof Buffer?Buffer.from(r,"base64"):Uint8Array.from(atob(r),(r=>r.codePointAt(0))):(new TextEncoder).encode(r)}export function stringToBase64(r){return typedArrayToBase64((new TextEncoder).encode(r))}export function typedArrayToBase64(r){const t=65534,n=[];for(let e=0;e<r.length;e+=t){const o=r.subarray(e,e+t);n.push(String.fromCodePoint.apply(null,o))}const e=n.join("");return btoa(e)}export function mergeUint8Arrays(r){let t=0;for(const n of r)t+=n.length;const n=new Uint8Array(t);let e=0;for(const t of r)n.set(t,e),e+=t.length;return n}